INSERT INTO pdf_insights (id, slug, language, title, subtitle, short_title, content_type, status, author, publication_date, data_period, page_count, reading_time, executive_thesis, short_summary, executive_summary, key_findings, leadership_implications, strategic_questions, methodology, limitations, regions, topics, expertise, keywords, gating_model, pdf_key, original_filename, checksum, mime_type, file_size, version, extraction_confidence, created_by, updated_by, created_at, updated_at) VALUES ('26659c0f-c191-412e-a455-d361f2274cae', 'machinery-regulation-no-transition-26659c0f', 'en', 'No transition period: what 20 January 2027 means for Turkish machinery exporters', 'The EU Machinery Regulation changes the evidence behind the CE mark, especially for software, connectivity and machine learning.', 'No transition period', 'Strategic Perspective', 'review_required', 'Ahmed Furkan Gul', '2026-10-24', 'October 2026', 5, 15, 'The EU Machinery Regulation changes the evidence behind the CE mark, especially for software, connectivity and machine learning.', 'Regulation (EU) 2023/1230 replaces the Machinery Directive for machinery placed on the EU market from 20 January 2027. There is no transition period: a machine shipped on or after that date must meet the new Regulation, whatever was true of the same model last year.', 'Regulation (EU) 2023/1230 replaces the Machinery Directive for machinery placed on the EU market from 20 January 2027. There is no transition period: a machine shipped on or after that date must meet the new Regulation, whatever was true of the same model last year. Most of the familiar logic stays: essential health and safety requirements, a risk assessment, a technical file, an EU declaration of conformity and the CE mark. What changes is the evidence. Safety-related software, protection against corruption of control systems, self-evolving behaviour and digital instructions now have to be documented explicitly. For a Turkish machinery exporter the practical risk is not the law itself but the calendar. Machines on order today may ship after 20 January 2027. The sound question is which product families need new evidence, which need a notified body, and which can be declared on the existing file with modest updates.', '[{"title": "No transition period", "explanation": "Regulation (EU) 2023/1230 replaces the Machinery Directive for machinery placed on the EU market from 20 January 2027. There is no transition period: a machine shipped on or after that date must meet the new Regulation, whatever was true of the same model last year.", "page": 2}, {"title": "The evidence changes", "explanation": "Most of the familiar logic stays: essential health and safety requirements, a risk assessment, a technical file, an EU declaration of conformity and the CE mark. What changes is the evidence. Safety-related software, protection against corruption of control systems, self-evolving behaviour and digital instructions now have to be documented explicitly.", "page": 2}, {"title": "Sequence the portfolio", "explanation": "For a Turkish machinery exporter the practical risk is not the law itself but the calendar. Machines on order today may ship after 20 January 2027. The sound question is which product families need new evidence, which need a notified body, and which can be declared on the existing file with modest updates.", "page": 2}]', '[]', '["Which product families ship into the EU on or after 20 January 2027, including orders already booked?", "Which of them fall into the high-risk categories of Annex I, and do any require a notified body?", "Where do safety functions depend on software, firmware, parameters or data?", "Which machines connect to networks, remote access or cloud services, and how are they protected against corruption?", "Is any safety-related behaviour adaptive or based on machine learning?", "Are our technical files and risk assessments current, and who owns them?", "How will we provide digital instructions and paper copies on request?", "Which customer contracts reference the Machinery Directive and need updating?"]', 'Desk review of official EU and Turkish sources checked on 23–24 October 2026, combined with Ganrich Advisory’s October 2026 review of opportunities in Türkiye.', 'General information, not legal, customs, tax or engineering advice. Rules and dates change; confirm against official sources. No client work or results are described.', '["Türkiye", "European Union"]', '["Machinery Regulation", "Product safety", "EU market access"]', '["Operating model"]', '["Machinery Regulation", "CE marking", "machine safety", "cybersecurity", "manufacturers"]', 'fully_ungated', 'pdf-insights/26659c0f-c191-412e-a455-d361f2274cae/v1/Ganrich-Machinery-Regulation-2027-EN.pdf', 'Ganrich-Machinery-Regulation-2027-EN.pdf', '3c1effdbd7ee255d0ae549b337d659375f0235ce133af342113917da34ad0558', 'application/pdf', 261307, 1, 'reviewed', 'furkangul@ganrichadvisory.com', 'furkangul@ganrichadvisory.com', '2026-10-24T09:00:00.000Z', '2026-10-24T09:00:00.000Z');
INSERT INTO pdf_insight_versions (id, insight_id, version, r2_key, filename, checksum, file_size, uploaded_by, uploaded_at, status) VALUES ('1b7f0d0e-1a40-4c55-9c71-000000000007', '26659c0f-c191-412e-a455-d361f2274cae', 1, 'pdf-insights/26659c0f-c191-412e-a455-d361f2274cae/v1/Ganrich-Machinery-Regulation-2027-EN.pdf', 'Ganrich-Machinery-Regulation-2027-EN.pdf', '3c1effdbd7ee255d0ae549b337d659375f0235ce133af342113917da34ad0558', 261307, 'furkangul@ganrichadvisory.com', '2026-10-24T09:00:00.000Z', 'current');
INSERT INTO pdf_insights (id, slug, language, title, subtitle, short_title, content_type, status, author, publication_date, data_period, page_count, reading_time, executive_thesis, short_summary, executive_summary, key_findings, leadership_implications, strategic_questions, methodology, limitations, regions, topics, expertise, keywords, gating_model, pdf_key, original_filename, checksum, mime_type, file_size, version, extraction_confidence, created_by, updated_by, created_at, updated_at) VALUES ('7d6aa9bd-69d1-40cb-8888-3a9bc97cc669', 'ppwr-packaging-file-7d6aa9bd', 'en', 'Packaging is now a regulated product: the PPWR file EU buyers will ask for', 'Since 12 August 2026 the packaging around your goods needs its own declaration, documentation and substance evidence.', 'Packaging is now a regulated product', 'Strategic Perspective', 'review_required', 'Ahmed Furkan Gul', '2026-10-24', 'October 2026', 5, 15, 'Since 12 August 2026 the packaging around your goods needs its own declaration, documentation and substance evidence.', 'The EU Packaging and Packaging Waste Regulation, Regulation (EU) 2025/40, has applied since 12 August 2026. Packaging placed on the EU market must now come with an EU declaration of conformity backed by technical documentation, and food-contact packaging must respect new limits on PFAS.', 'The EU Packaging and Packaging Waste Regulation, Regulation (EU) 2025/40, has applied since 12 August 2026. Packaging placed on the EU market must now come with an EU declaration of conformity backed by technical documentation, and food-contact packaging must respect new limits on PFAS. For Turkish exporters this reaches further than the packaging industry. Any company that ships goods into the EU in boxes, films, pallet wraps or retail packs is placing packaging on the market, and its EU customers are starting to ask who holds the file. The larger design obligations, such as recyclability grades, minimum recycled content and empty-space limits, arrive from 2028 and 2030. The decisions that make them affordable, about materials, formats and suppliers, are being taken now.', '[{"title": "The file is required now", "explanation": "The EU Packaging and Packaging Waste Regulation, Regulation (EU) 2025/40, has applied since 12 August 2026. Packaging placed on the EU market must now come with an EU declaration of conformity backed by technical documentation, and food-contact packaging must respect new limits on PFAS.", "page": 2}, {"title": "It reaches every exporter", "explanation": "For Turkish exporters this reaches further than the packaging industry. Any company that ships goods into the EU in boxes, films, pallet wraps or retail packs is placing packaging on the market, and its EU customers are starting to ask who holds the file.", "page": 2}, {"title": "Design decisions are due now", "explanation": "The larger design obligations, such as recyclability grades, minimum recycled content and empty-space limits, arrive from 2028 and 2030. The decisions that make them affordable, about materials, formats and suppliers, are being taken now.", "page": 2}]', '[]', '["How many packaging formats do we ship into the EU, and who is the manufacturer of each?", "In which member states are we, or our customers, the producer for extended producer responsibility?", "Do we have supplier declarations for substances of concern, and test evidence where risk is high?", "Which formats are food-contact packaging subject to the PFAS limits?", "Which formats will struggle with recyclability grades or empty-space limits from 2030?", "Have EU customers asked us for declarations of conformity or packaging data?", "Do we need an authorised representative in any member state?", "Who owns packaging compliance in our business today?"]', 'Desk review of official EU and Turkish sources checked on 23–24 October 2026, combined with Ganrich Advisory’s October 2026 review of opportunities in Türkiye.', 'General information, not legal, customs, tax or engineering advice. Rules and dates change; confirm against official sources. No client work or results are described.', '["Türkiye", "European Union"]', '["PPWR", "Packaging", "EU market access"]', '["Operating model"]', '["PPWR", "packaging", "PFAS", "EPR", "declaration of conformity"]', 'fully_ungated', 'pdf-insights/7d6aa9bd-69d1-40cb-8888-3a9bc97cc669/v1/Ganrich-PPWR-Packaging-File-EN.pdf', 'Ganrich-PPWR-Packaging-File-EN.pdf', 'bc743d8f7a53099b4d923059562739cc3a9fa99b4034ca9f380b336176a18301', 'application/pdf', 256214, 1, 'reviewed', 'furkangul@ganrichadvisory.com', 'furkangul@ganrichadvisory.com', '2026-10-24T09:00:00.000Z', '2026-10-24T09:00:00.000Z');
INSERT INTO pdf_insight_versions (id, insight_id, version, r2_key, filename, checksum, file_size, uploaded_by, uploaded_at, status) VALUES ('1b7f0d0e-1a40-4c55-9c71-000000000008', '7d6aa9bd-69d1-40cb-8888-3a9bc97cc669', 1, 'pdf-insights/7d6aa9bd-69d1-40cb-8888-3a9bc97cc669/v1/Ganrich-PPWR-Packaging-File-EN.pdf', 'Ganrich-PPWR-Packaging-File-EN.pdf', 'bc743d8f7a53099b4d923059562739cc3a9fa99b4034ca9f380b336176a18301', 256214, 'furkangul@ganrichadvisory.com', '2026-10-24T09:00:00.000Z', 'current');
INSERT INTO pdf_insights (id, slug, language, title, subtitle, short_title, content_type, status, author, publication_date, data_period, page_count, reading_time, executive_thesis, short_summary, executive_summary, key_findings, leadership_implications, strategic_questions, methodology, limitations, regions, topics, expertise, keywords, gating_model, pdf_key, original_filename, checksum, mime_type, file_size, version, extraction_confidence, created_by, updated_by, created_at, updated_at) VALUES ('9f541303-7f23-4342-bf86-23dd990efc4c', 'battery-passport-data-supply-chain-9f541303', 'en', 'The battery passport is a data supply chain: preparing for 18 February 2027', 'What Turkish battery, e-mobility and energy-storage manufacturers need in place before EU buyers scan the QR code.', 'The battery passport is a data supply chain', 'Strategic Perspective', 'review_required', 'Ahmed Furkan Gul', '2026-10-24', 'October 2026', 5, 15, 'What Turkish battery, e-mobility and energy-storage manufacturers need in place before EU buyers scan the QR code.', 'Under the EU Batteries Regulation, Regulation (EU) 2023/1542, all batteries placed on the EU market must carry a QR code from 18 February 2027. For electric-vehicle batteries, light means of transport batteries and industrial batteries above 2 kWh, that code must lead to a digital battery passport.', 'Under the EU Batteries Regulation, Regulation (EU) 2023/1542, all batteries placed on the EU market must carry a QR code from 18 February 2027. For electric-vehicle batteries, light means of transport batteries and industrial batteries above 2 kWh, that code must lead to a digital battery passport. The passport is not a label but a data set: identity, composition, carbon footprint, performance and durability, and, over time, recycled content. Much of that data sits with cell suppliers, material suppliers and test laboratories, not with the company whose name is on the pack. Due diligence obligations on cobalt, lithium, nickel and natural graphite follow from 18 August 2027 for larger operators. Exporters who start now can choose how to gather this data. Those who start late will accept whatever their buyers prescribe.', '[{"title": "QR codes and passports from February 2027", "explanation": "Under the EU Batteries Regulation, Regulation (EU) 2023/1542, all batteries placed on the EU market must carry a QR code from 18 February 2027. For electric-vehicle batteries, light means of transport batteries and industrial batteries above 2 kWh, that code must lead to a digital battery passport.", "page": 2}, {"title": "The data sits with suppliers", "explanation": "The passport is not a label but a data set: identity, composition, carbon footprint, performance and durability, and, over time, recycled content. Much of that data sits with cell suppliers, material suppliers and test laboratories, not with the company whose name is on the pack.", "page": 2}, {"title": "Due diligence follows in August 2027", "explanation": "Due diligence obligations on cobalt, lithium, nickel and natural graphite follow from 18 August 2027 for larger operators. Exporters who start now can choose how to gather this data. Those who start late will accept whatever their buyers prescribe.", "page": 2}]', '[]', '["Which of our battery products fall into the EV, LMT or industrial above 2 kWh categories?", "Who is the economic operator placing each product on the EU market?", "Which passport data do we hold, and which must come from cell and material suppliers?", "Do our supplier contracts oblige them to provide that data, and in what format?", "Which products contain portable batteries affected by the removability rules?", "Are our larger EU customers in scope for due diligence, and what have they asked for?", "Which passport platform or service will we use, and who maintains the records?", "How will we keep datasheets, tenders and passport data consistent?"]', 'Desk review of official EU and Turkish sources checked on 23–24 October 2026, combined with Ganrich Advisory’s October 2026 review of opportunities in Türkiye.', 'General information, not legal, customs, tax or engineering advice. Rules and dates change; confirm against official sources. No client work or results are described.', '["Türkiye", "European Union"]', '["Batteries Regulation", "Battery passport", "EU market access"]', '["Market entry"]', '["battery passport", "Batteries Regulation", "e-mobility", "energy storage", "due diligence"]', 'fully_ungated', 'pdf-insights/9f541303-7f23-4342-bf86-23dd990efc4c/v1/Ganrich-Battery-Passport-2027-EN.pdf', 'Ganrich-Battery-Passport-2027-EN.pdf', 'c3c23ad43374218a5adf4269efe3dc7ffe32f67314e14fa57d96373ac0dc06d0', 'application/pdf', 257772, 1, 'reviewed', 'furkangul@ganrichadvisory.com', 'furkangul@ganrichadvisory.com', '2026-10-24T09:00:00.000Z', '2026-10-24T09:00:00.000Z');
INSERT INTO pdf_insight_versions (id, insight_id, version, r2_key, filename, checksum, file_size, uploaded_by, uploaded_at, status) VALUES ('1b7f0d0e-1a40-4c55-9c71-000000000009', '9f541303-7f23-4342-bf86-23dd990efc4c', 1, 'pdf-insights/9f541303-7f23-4342-bf86-23dd990efc4c/v1/Ganrich-Battery-Passport-2027-EN.pdf', 'Ganrich-Battery-Passport-2027-EN.pdf', 'c3c23ad43374218a5adf4269efe3dc7ffe32f67314e14fa57d96373ac0dc06d0', 257772, 'furkangul@ganrichadvisory.com', '2026-10-24T09:00:00.000Z', 'current');
INSERT INTO pdf_insights (id, slug, language, title, subtitle, short_title, content_type, status, author, publication_date, data_period, page_count, reading_time, executive_thesis, short_summary, executive_summary, key_findings, leadership_implications, strategic_questions, methodology, limitations, regions, topics, expertise, keywords, gating_model, pdf_key, original_filename, checksum, mime_type, file_size, version, extraction_confidence, created_by, updated_by, created_at, updated_at) VALUES ('a099a490-7315-4599-b5dd-ea17b0949801', 'forced-labour-proof-not-policy-a099a490', 'en', 'Proof, not policy: forced labour evidence for Turkish suppliers to EU buyers', 'The EU ban on products made with forced labour applies from 14 December 2027. Buyers are already asking suppliers what they can show.', 'Proof, not policy', 'Strategic Perspective', 'review_required', 'Ahmed Furkan Gul', '2026-10-24', 'October 2026', 4, 12, 'The EU ban on products made with forced labour applies from 14 December 2027. Buyers are already asking suppliers what they can show.', 'Regulation (EU) 2024/3015 prohibits placing on the EU market, making available or exporting any product made wholly or partly with forced labour. It applies from 14 December 2027, and the European Commission published guidelines on 30 June 2026.', 'Regulation (EU) 2024/3015 prohibits placing on the EU market, making available or exporting any product made wholly or partly with forced labour. It applies from 14 December 2027, and the European Commission published guidelines on 30 June 2026. The ban applies to products, not companies, and has no size threshold. A product found to be tainted can be withdrawn and disposed of at the operator’s expense, and good due diligence does not by itself prevent a prohibition. For Turkish suppliers in long, labour-intensive chains, such as garments and textiles or products with seasonal agricultural labour, the commercial question is simple: when an EU buyer asks for traceability and labour evidence, can we provide it quickly and credibly?', '[{"title": "A product ban from December 2027", "explanation": "Regulation (EU) 2024/3015 prohibits placing on the EU market, making available or exporting any product made wholly or partly with forced labour. It applies from 14 December 2027, and the European Commission published guidelines on 30 June 2026.", "page": 2}, {"title": "No size threshold, no safe harbour", "explanation": "The ban applies to products, not companies, and has no size threshold. A product found to be tainted can be withdrawn and disposed of at the operator’s expense, and good due diligence does not by itself prevent a prohibition.", "page": 2}, {"title": "Evidence wins business", "explanation": "For Turkish suppliers in long, labour-intensive chains, such as garments and textiles or products with seasonal agricultural labour, the commercial question is simple: when an EU buyer asks for traceability and labour evidence, can we provide it quickly and credibly?", "page": 2}]', '[]', '["Which of our products and inputs carry the highest forced labour risk, and why?", "Can we trace those products to each processing step and subcontractor?", "What evidence do we hold on labour conditions at those tiers: audits, worker interviews, grievance channels?", "How quickly could we answer a detailed traceability request from an EU buyer?", "Which customer contracts now include forced labour or traceability clauses?", "How do we handle a suspected issue at a supplier, and who decides?", "Do we use the Commission’s risk database or other recognised risk sources?", "Who owns this topic in our business, and does the board see it?"]', 'Desk review of official EU and Turkish sources checked on 23–24 October 2026, combined with Ganrich Advisory’s October 2026 review of opportunities in Türkiye.', 'General information, not legal, customs, tax or engineering advice. Rules and dates change; confirm against official sources. No client work or results are described.', '["Türkiye", "European Union"]', '["Forced Labour Regulation", "Supply chain", "EU market access"]', '["Operating model"]', '["forced labour", "traceability", "textiles", "supply chain", "due diligence"]', 'fully_ungated', 'pdf-insights/a099a490-7315-4599-b5dd-ea17b0949801/v1/Ganrich-Forced-Labour-Evidence-EN.pdf', 'Ganrich-Forced-Labour-Evidence-EN.pdf', 'ba80588f9f4727100b677eeb2843a831b12eaa9d4bf885b7470ab238bcacded4', 'application/pdf', 259741, 1, 'reviewed', 'furkangul@ganrichadvisory.com', 'furkangul@ganrichadvisory.com', '2026-10-24T09:00:00.000Z', '2026-10-24T09:00:00.000Z');
INSERT INTO pdf_insight_versions (id, insight_id, version, r2_key, filename, checksum, file_size, uploaded_by, uploaded_at, status) VALUES ('1b7f0d0e-1a40-4c55-9c71-000000000010', 'a099a490-7315-4599-b5dd-ea17b0949801', 1, 'pdf-insights/a099a490-7315-4599-b5dd-ea17b0949801/v1/Ganrich-Forced-Labour-Evidence-EN.pdf', 'Ganrich-Forced-Labour-Evidence-EN.pdf', 'ba80588f9f4727100b677eeb2843a831b12eaa9d4bf885b7470ab238bcacded4', 259741, 'furkangul@ganrichadvisory.com', '2026-10-24T09:00:00.000Z', 'current');
INSERT INTO pdf_insights (id, slug, language, title, subtitle, short_title, content_type, status, author, publication_date, data_period, page_count, reading_time, executive_thesis, short_summary, executive_summary, key_findings, leadership_implications, strategic_questions, methodology, limitations, regions, topics, expertise, keywords, gating_model, pdf_key, original_filename, checksum, mime_type, file_size, version, extraction_confidence, created_by, updated_by, created_at, updated_at) VALUES ('d75e501c-9502-4c3a-a6bd-54d8d62f9aa4', 'turkiye-ets-monitoring-before-money-d75e501c', 'en', 'Monitoring before money: getting ready for Türkiye’s emissions trading system', 'The ETS Regulation published in August 2026 starts with plans, permits and verified reports. The carbon price comes later.', 'Monitoring before money', 'Strategic Perspective', 'review_required', 'Ahmed Furkan Gul', '2026-10-24', 'October 2026', 5, 15, 'The ETS Regulation published in August 2026 starts with plans, permits and verified reports. The carbon price comes later.', 'Türkiye’s Climate Law, Law No. 7552, was published on 9 July 2025 and created the legal basis for a national emissions trading system. The Türkiye Emissions Trading System Regulation followed in the Official Gazette No. 33353 on 27 August 2026 and entered into force the same day.', 'Türkiye’s Climate Law, Law No. 7552, was published on 9 July 2025 and created the legal basis for a national emissions trading system. The Türkiye Emissions Trading System Regulation followed in the Official Gazette No. 33353 on 27 August 2026 and entered into force the same day. Installations with annual emissions above 50,000 tonnes of CO2 equivalent fall within the ETS. Smaller installations in the listed activities must still monitor, report and verify their emissions. Covered operators need an emissions permit, an approved monitoring plan and an annual verified emissions report due by 30 April. The pilot phase is designed to test monitoring, reporting, verification and allocation before costs bite. That makes it the cheapest moment to get the data right, and the same data underpins the emissions figures EU buyers request under CBAM.', '[{"title": "The legal basis is in place", "explanation": "Türkiye’s Climate Law, Law No. 7552, was published on 9 July 2025 and created the legal basis for a national emissions trading system. The Türkiye Emissions Trading System Regulation followed in the Official Gazette No. 33353 on 27 August 2026 and entered into force the same day.", "page": 2}, {"title": "Thresholds and duties", "explanation": "Installations with annual emissions above 50,000 tonnes of CO2 equivalent fall within the ETS. Smaller installations in the listed activities must still monitor, report and verify their emissions. Covered operators need an emissions permit, an approved monitoring plan and an annual verified emissions report due by 30 April.", "page": 2}, {"title": "The pilot is the cheap moment", "explanation": "The pilot phase is designed to test monitoring, reporting, verification and allocation before costs bite. That makes it the cheapest moment to get the data right, and the same data underpins the emissions figures EU buyers request under CBAM.", "page": 2}]', '[]', '["Which of our installations fall into which category, and are any close to a threshold?", "Do we hold a valid emissions permit, or know when we must apply?", "Is our monitoring plan approved, current and aligned with how the plant actually runs?", "Where do fuel, material and production data come from, and how reliable are the meters?", "Who prepares the annual report, and which accredited verifier will check it?", "How could free allocation and allowance prices affect our margins in the first implementation period?", "Can the same data serve our EU customers’ CBAM requests?", "Who owns carbon data in our business, and how often does leadership see it?"]', 'Desk review of official EU and Turkish sources checked on 23–24 October 2026, combined with Ganrich Advisory’s October 2026 review of opportunities in Türkiye.', 'General information, not legal, customs, tax or engineering advice. Rules and dates change; confirm against official sources. No client work or results are described.', '["Türkiye", "European Union"]', '["Türkiye ETS", "Carbon", "Industrial plants"]', '["Operating model"]', '["Türkiye ETS", "emissions trading", "MRV", "monitoring plan", "CBAM"]', 'fully_ungated', 'pdf-insights/d75e501c-9502-4c3a-a6bd-54d8d62f9aa4/v1/Ganrich-Turkiye-ETS-Readiness-EN.pdf', 'Ganrich-Turkiye-ETS-Readiness-EN.pdf', 'fe5348d3b33cdd6159700b4bbba15daad8cdd81f2abfb35bb1c54d9682b67b2c', 'application/pdf', 264642, 1, 'reviewed', 'furkangul@ganrichadvisory.com', 'furkangul@ganrichadvisory.com', '2026-10-24T09:00:00.000Z', '2026-10-24T09:00:00.000Z');
INSERT INTO pdf_insight_versions (id, insight_id, version, r2_key, filename, checksum, file_size, uploaded_by, uploaded_at, status) VALUES ('1b7f0d0e-1a40-4c55-9c71-000000000011', 'd75e501c-9502-4c3a-a6bd-54d8d62f9aa4', 1, 'pdf-insights/d75e501c-9502-4c3a-a6bd-54d8d62f9aa4/v1/Ganrich-Turkiye-ETS-Readiness-EN.pdf', 'Ganrich-Turkiye-ETS-Readiness-EN.pdf', 'fe5348d3b33cdd6159700b4bbba15daad8cdd81f2abfb35bb1c54d9682b67b2c', 264642, 'furkangul@ganrichadvisory.com', '2026-10-24T09:00:00.000Z', 'current');
INSERT INTO pdf_insights (id, slug, language, title, subtitle, short_title, content_type, status, author, publication_date, data_period, page_count, reading_time, executive_thesis, short_summary, executive_summary, key_findings, leadership_implications, strategic_questions, methodology, limitations, regions, topics, expertise, keywords, gating_model, pdf_key, original_filename, checksum, mime_type, file_size, version, extraction_confidence, created_by, updated_by, created_at, updated_at) VALUES ('6cec1c86-9fb9-4d4e-b6dd-59c17d99dff3', 'makine-tuzugu-gecis-suresi-yok-6cec1c86', 'tr', 'Geçiş süresi yok: 20 Ocak 2027 Türk makine ihracatçıları için ne anlama geliyor?', 'AB Makine Tüzüğü, CE işaretinin arkasındaki kanıtı değiştiriyor; özellikle yazılım, bağlantı ve makine öğrenmesi konusunda.', 'Geçiş süresi yok', 'Strategic Perspective', 'review_required', 'Ahmed Furkan Gul', '2026-10-24', 'Ekim 2026', 5, 15, 'AB Makine Tüzüğü, CE işaretinin arkasındaki kanıtı değiştiriyor; özellikle yazılım, bağlantı ve makine öğrenmesi konusunda.', '(AB) 2023/1230 sayılı Tüzük, 20 Ocak 2027’den itibaren AB pazarına arz edilen makineler için Makine Direktifinin yerini alıyor. Geçiş süresi yok: Bu tarihte veya sonrasında sevk edilen bir makine, aynı model geçen yıl ne durumda olursa olsun yeni Tüzüğe uymak zorunda.', '(AB) 2023/1230 sayılı Tüzük, 20 Ocak 2027’den itibaren AB pazarına arz edilen makineler için Makine Direktifinin yerini alıyor. Geçiş süresi yok: Bu tarihte veya sonrasında sevk edilen bir makine, aynı model geçen yıl ne durumda olursa olsun yeni Tüzüğe uymak zorunda. Tanıdık mantığın büyük kısmı korunuyor: temel sağlık ve güvenlik gereklilikleri, risk değerlendirmesi, teknik dosya, AB uygunluk beyanı ve CE işareti. Değişen şey kanıt. Güvenlikle ilgili yazılım, kontrol sistemlerinin bozulmaya karşı korunması, kendi kendine gelişen davranış ve dijital kullanım kılavuzu artık açıkça belgelenmeli. Türk makine ihracatçısı için asıl risk mevzuatın kendisi değil, takvim. Bugün sipariş alınan makineler 20 Ocak 2027’den sonra sevk edilebilir. Doğru soru, hangi ürün ailelerinin yeni kanıta, hangilerinin onaylanmış kuruluşa ihtiyaç duyduğu ve hangilerinin mevcut dosyada küçük güncellemelerle beyan edilebileceğidir.', '[{"title": "Geçiş süresi yok", "explanation": "(AB) 2023/1230 sayılı Tüzük, 20 Ocak 2027’den itibaren AB pazarına arz edilen makineler için Makine Direktifinin yerini alıyor. Geçiş süresi yok: Bu tarihte veya sonrasında sevk edilen bir makine, aynı model geçen yıl ne durumda olursa olsun yeni Tüzüğe uymak zorunda.", "page": 2}, {"title": "Kanıt değişiyor", "explanation": "Tanıdık mantığın büyük kısmı korunuyor: temel sağlık ve güvenlik gereklilikleri, risk değerlendirmesi, teknik dosya, AB uygunluk beyanı ve CE işareti. Değişen şey kanıt. Güvenlikle ilgili yazılım, kontrol sistemlerinin bozulmaya karşı korunması, kendi kendine gelişen davranış ve dijital kullanım kılavuzu artık açıkça belgelenmeli.", "page": 2}, {"title": "Portföyü sıraya koyun", "explanation": "Türk makine ihracatçısı için asıl risk mevzuatın kendisi değil, takvim. Bugün sipariş alınan makineler 20 Ocak 2027’den sonra sevk edilebilir. Doğru soru, hangi ürün ailelerinin yeni kanıta, hangilerinin onaylanmış kuruluşa ihtiyaç duyduğu ve hangilerinin mevcut dosyada küçük güncellemelerle beyan edilebileceğidir.", "page": 2}]', '[]', '["Hangi ürün ailelerimiz, alınmış siparişler dahil, 20 Ocak 2027’de veya sonrasında AB’ye sevk edilecek?", "Bunlardan hangileri I. Ekteki yüksek riskli kategorilere giriyor; onaylanmış kuruluş gerektiren var mı?", "Güvenlik fonksiyonları nerede yazılıma, ürün yazılımına, parametrelere veya veriye bağlı?", "Hangi makineler ağlara, uzaktan erişime veya bulut hizmetlerine bağlanıyor ve bozulmaya karşı nasıl korunuyor?", "Güvenlikle ilgili herhangi bir davranış uyarlanabilir mi veya makine öğrenmesine mi dayanıyor?", "Teknik dosyalarımız ve risk değerlendirmelerimiz güncel mi; sahibi kim?", "Dijital kılavuzu ve talep üzerine basılı kopyayı nasıl sağlayacağız?", "Hangi müşteri sözleşmeleri Makine Direktifine atıf yapıyor ve güncellenmeli?"]', '23–24 Ekim 2026’da kontrol edilen resmî AB ve Türkiye kaynaklarının masa başı incelemesi ile Ganrich Advisory’nin Ekim 2026 Türkiye fırsat incelemesinin birleşimi.', 'Genel bilgi niteliğindedir; hukuki, gümrük, vergi veya mühendislik danışmanlığı değildir. Kurallar ve tarihler değişebilir; resmî kaynaklardan teyit edin. Müşteri çalışması veya sonucu anlatılmaz.', '["Türkiye", "European Union"]', '["Machinery Regulation", "Product safety", "EU market access"]', '["Operating model"]', '["Machinery Regulation", "CE marking", "machine safety", "cybersecurity", "manufacturers"]', 'fully_ungated', 'pdf-insights/6cec1c86-9fb9-4d4e-b6dd-59c17d99dff3/v1/Ganrich-Makine-Tuzugu-2027-TR.pdf', 'Ganrich-Makine-Tuzugu-2027-TR.pdf', 'fe9b436f85cfd75c207c866287c3ece6497e0498f3fa3d4fd91722948adc4f19', 'application/pdf', 271720, 1, 'reviewed', 'furkangul@ganrichadvisory.com', 'furkangul@ganrichadvisory.com', '2026-10-24T09:00:00.000Z', '2026-10-24T09:00:00.000Z');
INSERT INTO pdf_insight_versions (id, insight_id, version, r2_key, filename, checksum, file_size, uploaded_by, uploaded_at, status) VALUES ('1b7f0d0e-1a40-4c55-9c71-000000000012', '6cec1c86-9fb9-4d4e-b6dd-59c17d99dff3', 1, 'pdf-insights/6cec1c86-9fb9-4d4e-b6dd-59c17d99dff3/v1/Ganrich-Makine-Tuzugu-2027-TR.pdf', 'Ganrich-Makine-Tuzugu-2027-TR.pdf', 'fe9b436f85cfd75c207c866287c3ece6497e0498f3fa3d4fd91722948adc4f19', 271720, 'furkangul@ganrichadvisory.com', '2026-10-24T09:00:00.000Z', 'current');
INSERT INTO pdf_insights (id, slug, language, title, subtitle, short_title, content_type, status, author, publication_date, data_period, page_count, reading_time, executive_thesis, short_summary, executive_summary, key_findings, leadership_implications, strategic_questions, methodology, limitations, regions, topics, expertise, keywords, gating_model, pdf_key, original_filename, checksum, mime_type, file_size, version, extraction_confidence, created_by, updated_by, created_at, updated_at) VALUES ('65f6be90-b829-44c8-8568-e0c3064fb7f5', 'ppwr-ambalaj-dosyasi-65f6be90', 'tr', 'Ambalaj artık düzenlenmiş bir ürün: AB alıcılarının isteyeceği PPWR dosyası', '12 Ağustos 2026’dan beri mallarınızı saran ambalajın kendi beyanı, belgesi ve madde kanıtı olması gerekiyor.', 'Ambalaj artık düzenlenmiş bir ürün', 'Strategic Perspective', 'review_required', 'Ahmed Furkan Gul', '2026-10-24', 'Ekim 2026', 5, 15, '12 Ağustos 2026’dan beri mallarınızı saran ambalajın kendi beyanı, belgesi ve madde kanıtı olması gerekiyor.', 'AB Ambalaj ve Ambalaj Atıkları Tüzüğü, yani (AB) 2025/40 sayılı Tüzük (PPWR), 12 Ağustos 2026’dan beri uygulanıyor. AB pazarına arz edilen ambalajın artık teknik dokümantasyonla desteklenen bir AB uygunluk beyanı olmalı; gıdayla temas eden ambalaj da PFAS için yeni sınırlara uymalı.', 'AB Ambalaj ve Ambalaj Atıkları Tüzüğü, yani (AB) 2025/40 sayılı Tüzük (PPWR), 12 Ağustos 2026’dan beri uygulanıyor. AB pazarına arz edilen ambalajın artık teknik dokümantasyonla desteklenen bir AB uygunluk beyanı olmalı; gıdayla temas eden ambalaj da PFAS için yeni sınırlara uymalı. Türk ihracatçılar için bu, ambalaj sektörünün çok ötesine uzanıyor. Malını AB’ye koli, film, palet streçi veya perakende ambalajla gönderen her şirket ambalajı piyasaya arz ediyor ve AB’deki müşterileri dosyanın kimde olduğunu sormaya başladı. Geri dönüştürülebilirlik sınıfları, asgari geri dönüştürülmüş içerik ve boş alan sınırları gibi büyük tasarım yükümlülükleri 2028 ve 2030’dan itibaren geliyor. Bunları karşılanabilir kılacak malzeme, format ve tedarikçi kararları ise bugün veriliyor.', '[{"title": "Dosya artık zorunlu", "explanation": "AB Ambalaj ve Ambalaj Atıkları Tüzüğü, yani (AB) 2025/40 sayılı Tüzük (PPWR), 12 Ağustos 2026’dan beri uygulanıyor. AB pazarına arz edilen ambalajın artık teknik dokümantasyonla desteklenen bir AB uygunluk beyanı olmalı; gıdayla temas eden ambalaj da PFAS için yeni sınırlara uymalı.", "page": 2}, {"title": "Her ihracatçıya ulaşıyor", "explanation": "Türk ihracatçılar için bu, ambalaj sektörünün çok ötesine uzanıyor. Malını AB’ye koli, film, palet streçi veya perakende ambalajla gönderen her şirket ambalajı piyasaya arz ediyor ve AB’deki müşterileri dosyanın kimde olduğunu sormaya başladı.", "page": 2}, {"title": "Tasarım kararlarının zamanı şimdi", "explanation": "Geri dönüştürülebilirlik sınıfları, asgari geri dönüştürülmüş içerik ve boş alan sınırları gibi büyük tasarım yükümlülükleri 2028 ve 2030’dan itibaren geliyor. Bunları karşılanabilir kılacak malzeme, format ve tedarikçi kararları ise bugün veriliyor.", "page": 2}]', '[]', '["AB’ye kaç ambalaj formatı gönderiyoruz ve her birinin üreticisi kim?", "Hangi üye devletlerde biz veya müşterilerimiz genişletilmiş üretici sorumluluğu açısından üreticiyiz?", "Endişe verici maddeler için tedarikçi beyanlarımız ve riskin yüksek olduğu yerlerde test kanıtımız var mı?", "Hangi formatlar PFAS sınırlarına tabi gıda temaslı ambalaj?", "Hangi formatlar 2030’dan itibaren geri dönüştürülebilirlik sınıfı veya boş alan sınırlarında zorlanacak?", "AB müşterileri bizden uygunluk beyanı veya ambalaj verisi istedi mi?", "Herhangi bir üye devlette yetkili temsilciye ihtiyacımız var mı?", "Bugün şirketimizde ambalaj uyumunun sahibi kim?"]', '23–24 Ekim 2026’da kontrol edilen resmî AB ve Türkiye kaynaklarının masa başı incelemesi ile Ganrich Advisory’nin Ekim 2026 Türkiye fırsat incelemesinin birleşimi.', 'Genel bilgi niteliğindedir; hukuki, gümrük, vergi veya mühendislik danışmanlığı değildir. Kurallar ve tarihler değişebilir; resmî kaynaklardan teyit edin. Müşteri çalışması veya sonucu anlatılmaz.', '["Türkiye", "European Union"]', '["PPWR", "Packaging", "EU market access"]', '["Operating model"]', '["PPWR", "packaging", "PFAS", "EPR", "declaration of conformity"]', 'fully_ungated', 'pdf-insights/65f6be90-b829-44c8-8568-e0c3064fb7f5/v1/Ganrich-PPWR-Ambalaj-Dosyasi-TR.pdf', 'Ganrich-PPWR-Ambalaj-Dosyasi-TR.pdf', 'cdb0b08b8a36431ed878a266c359fa03db0e65ee91cf00d4e13dc07e4518eba1', 'application/pdf', 268306, 1, 'reviewed', 'furkangul@ganrichadvisory.com', 'furkangul@ganrichadvisory.com', '2026-10-24T09:00:00.000Z', '2026-10-24T09:00:00.000Z');
INSERT INTO pdf_insight_versions (id, insight_id, version, r2_key, filename, checksum, file_size, uploaded_by, uploaded_at, status) VALUES ('1b7f0d0e-1a40-4c55-9c71-000000000013', '65f6be90-b829-44c8-8568-e0c3064fb7f5', 1, 'pdf-insights/65f6be90-b829-44c8-8568-e0c3064fb7f5/v1/Ganrich-PPWR-Ambalaj-Dosyasi-TR.pdf', 'Ganrich-PPWR-Ambalaj-Dosyasi-TR.pdf', 'cdb0b08b8a36431ed878a266c359fa03db0e65ee91cf00d4e13dc07e4518eba1', 268306, 'furkangul@ganrichadvisory.com', '2026-10-24T09:00:00.000Z', 'current');
INSERT INTO pdf_insights (id, slug, language, title, subtitle, short_title, content_type, status, author, publication_date, data_period, page_count, reading_time, executive_thesis, short_summary, executive_summary, key_findings, leadership_implications, strategic_questions, methodology, limitations, regions, topics, expertise, keywords, gating_model, pdf_key, original_filename, checksum, mime_type, file_size, version, extraction_confidence, created_by, updated_by, created_at, updated_at) VALUES ('11d198db-9b3a-41ba-92fd-c08b1f0ea8b9', 'batarya-pasaportu-veri-zinciri-11d198db', 'tr', 'Batarya pasaportu bir veri tedarik zinciridir: 18 Şubat 2027’ye hazırlık', 'Türk batarya, e-mobilite ve enerji depolama üreticilerinin, AB alıcıları QR kodu okutmadan önce hazır etmesi gerekenler.', 'Batarya pasaportu bir veri tedarik zinciridir', 'Strategic Perspective', 'review_required', 'Ahmed Furkan Gul', '2026-10-24', 'Ekim 2026', 4, 12, 'Türk batarya, e-mobilite ve enerji depolama üreticilerinin, AB alıcıları QR kodu okutmadan önce hazır etmesi gerekenler.', 'AB Batarya Tüzüğü, yani (AB) 2023/1542 sayılı Tüzük uyarınca, AB pazarına arz edilen tüm bataryalar 18 Şubat 2027’den itibaren QR kod taşımalı. Elektrikli araç bataryaları, hafif ulaşım aracı (LMT) bataryaları ve 2 kWh’nin üzerindeki endüstriyel bataryalarda bu kod dijital batarya pasaportuna açılmalı.', 'AB Batarya Tüzüğü, yani (AB) 2023/1542 sayılı Tüzük uyarınca, AB pazarına arz edilen tüm bataryalar 18 Şubat 2027’den itibaren QR kod taşımalı. Elektrikli araç bataryaları, hafif ulaşım aracı (LMT) bataryaları ve 2 kWh’nin üzerindeki endüstriyel bataryalarda bu kod dijital batarya pasaportuna açılmalı. Pasaport bir etiket değil, bir veri setidir: kimlik, bileşim, karbon ayak izi, performans ve dayanıklılık ve zamanla geri dönüştürülmüş içerik. Bu verinin büyük kısmı, paketin üzerinde adı yazan şirkette değil; hücre tedarikçilerinde, malzeme tedarikçilerinde ve test laboratuvarlarında duruyor. Kobalt, lityum, nikel ve doğal grafit için durum tespiti yükümlülükleri 18 Ağustos 2027’den itibaren daha büyük işletmelere uygulanacak. Şimdi başlayan ihracatçılar bu veriyi nasıl toplayacaklarını kendileri seçebilir. Geç başlayanlar ise alıcının dayattığı yolu kabul eder.', '[{"title": "Şubat 2027’den itibaren QR kod ve pasaport", "explanation": "AB Batarya Tüzüğü, yani (AB) 2023/1542 sayılı Tüzük uyarınca, AB pazarına arz edilen tüm bataryalar 18 Şubat 2027’den itibaren QR kod taşımalı. Elektrikli araç bataryaları, hafif ulaşım aracı (LMT) bataryaları ve 2 kWh’nin üzerindeki endüstriyel bataryalarda bu kod dijital batarya pasaportuna açılmalı.", "page": 2}, {"title": "Veri tedarikçilerde", "explanation": "Pasaport bir etiket değil, bir veri setidir: kimlik, bileşim, karbon ayak izi, performans ve dayanıklılık ve zamanla geri dönüştürülmüş içerik. Bu verinin büyük kısmı, paketin üzerinde adı yazan şirkette değil; hücre tedarikçilerinde, malzeme tedarikçilerinde ve test laboratuvarlarında duruyor.", "page": 2}, {"title": "Durum tespiti Ağustos 2027’de", "explanation": "Kobalt, lityum, nikel ve doğal grafit için durum tespiti yükümlülükleri 18 Ağustos 2027’den itibaren daha büyük işletmelere uygulanacak. Şimdi başlayan ihracatçılar bu veriyi nasıl toplayacaklarını kendileri seçebilir. Geç başlayanlar ise alıcının dayattığı yolu kabul eder.", "page": 2}]', '[]', '["Hangi batarya ürünlerimiz elektrikli araç, LMT veya 2 kWh üzeri endüstriyel kategoriye giriyor?", "Her ürünü AB pazarına arz eden ekonomik işletmeci kim?", "Pasaport verisinin hangisi bizde, hangisi hücre ve malzeme tedarikçilerinden gelmeli?", "Tedarikçi sözleşmelerimiz bu veriyi hangi formatta vermeyi zorunlu kılıyor?", "Hangi ürünlerimizde sökülebilirlik kurallarından etkilenen taşınabilir batarya var?", "Büyük AB müşterilerimiz durum tespiti kapsamında mı ve ne istediler?", "Hangi pasaport platformunu veya hizmetini kullanacağız; kayıtları kim tutacak?", "Teknik föy, ihale ve pasaport verisini nasıl tutarlı tutacağız?"]', '23–24 Ekim 2026’da kontrol edilen resmî AB ve Türkiye kaynaklarının masa başı incelemesi ile Ganrich Advisory’nin Ekim 2026 Türkiye fırsat incelemesinin birleşimi.', 'Genel bilgi niteliğindedir; hukuki, gümrük, vergi veya mühendislik danışmanlığı değildir. Kurallar ve tarihler değişebilir; resmî kaynaklardan teyit edin. Müşteri çalışması veya sonucu anlatılmaz.', '["Türkiye", "European Union"]', '["Batteries Regulation", "Battery passport", "EU market access"]', '["Market entry"]', '["battery passport", "Batteries Regulation", "e-mobility", "energy storage", "due diligence"]', 'fully_ungated', 'pdf-insights/11d198db-9b3a-41ba-92fd-c08b1f0ea8b9/v1/Ganrich-Batarya-Pasaportu-2027-TR.pdf', 'Ganrich-Batarya-Pasaportu-2027-TR.pdf', '57ac57d3d47d38720527546c57584dd61538ad90657bab2447c53db3beebc52a', 'application/pdf', 268556, 1, 'reviewed', 'furkangul@ganrichadvisory.com', 'furkangul@ganrichadvisory.com', '2026-10-24T09:00:00.000Z', '2026-10-24T09:00:00.000Z');
INSERT INTO pdf_insight_versions (id, insight_id, version, r2_key, filename, checksum, file_size, uploaded_by, uploaded_at, status) VALUES ('1b7f0d0e-1a40-4c55-9c71-000000000014', '11d198db-9b3a-41ba-92fd-c08b1f0ea8b9', 1, 'pdf-insights/11d198db-9b3a-41ba-92fd-c08b1f0ea8b9/v1/Ganrich-Batarya-Pasaportu-2027-TR.pdf', 'Ganrich-Batarya-Pasaportu-2027-TR.pdf', '57ac57d3d47d38720527546c57584dd61538ad90657bab2447c53db3beebc52a', 268556, 'furkangul@ganrichadvisory.com', '2026-10-24T09:00:00.000Z', 'current');
INSERT INTO pdf_insights (id, slug, language, title, subtitle, short_title, content_type, status, author, publication_date, data_period, page_count, reading_time, executive_thesis, short_summary, executive_summary, key_findings, leadership_implications, strategic_questions, methodology, limitations, regions, topics, expertise, keywords, gating_model, pdf_key, original_filename, checksum, mime_type, file_size, version, extraction_confidence, created_by, updated_by, created_at, updated_at) VALUES ('492125d0-5706-4a92-a97c-d916dae88e29', 'zorla-calistirma-politika-degil-kanit-492125d0', 'tr', 'Politika değil kanıt: AB alıcılarına tedarik yapan Türk firmaları için zorla çalıştırma kanıtı', 'AB’nin zorla çalıştırmayla üretilen ürünlere yönelik yasağı 14 Aralık 2027’de uygulanmaya başlıyor. Alıcılar şimdiden tedarikçilere neyi gösterebildiklerini soruyor.', 'Politika değil kanıt', 'Strategic Perspective', 'review_required', 'Ahmed Furkan Gul', '2026-10-24', 'Ekim 2026', 4, 12, 'AB’nin zorla çalıştırmayla üretilen ürünlere yönelik yasağı 14 Aralık 2027’de uygulanmaya başlıyor. Alıcılar şimdiden tedarikçilere neyi gösterebildiklerini soruyor.', '(AB) 2024/3015 sayılı Tüzük, tamamen veya kısmen zorla çalıştırmayla üretilmiş herhangi bir ürünün AB pazarına arz edilmesini, piyasada bulundurulmasını veya AB’den ihraç edilmesini yasaklıyor. Tüzük 14 Aralık 2027’den itibaren uygulanıyor; Avrupa Komisyonu rehberini 30 Haziran 2026’da yayımladı.', '(AB) 2024/3015 sayılı Tüzük, tamamen veya kısmen zorla çalıştırmayla üretilmiş herhangi bir ürünün AB pazarına arz edilmesini, piyasada bulundurulmasını veya AB’den ihraç edilmesini yasaklıyor. Tüzük 14 Aralık 2027’den itibaren uygulanıyor; Avrupa Komisyonu rehberini 30 Haziran 2026’da yayımladı. Yasak şirketlere değil ürünlere uygulanıyor ve büyüklük eşiği yok. Zorla çalıştırma içerdiği tespit edilen bir ürün piyasadan çekilebilir ve masrafı işletmeciye ait olmak üzere bertaraf edilebilir; iyi bir durum tespiti tek başına yasağı önlemiyor. Hazır giyim ve tekstil ya da mevsimlik tarım işçiliği içeren ürünler gibi uzun ve emek yoğun zincirlerdeki Türk tedarikçiler için ticari soru basit: Bir AB alıcısı izlenebilirlik ve çalışma koşullarına dair kanıt istediğinde bunu hızlı ve inandırıcı biçimde sunabiliyor muyuz?', '[{"title": "Aralık 2027’den itibaren ürün yasağı", "explanation": "(AB) 2024/3015 sayılı Tüzük, tamamen veya kısmen zorla çalıştırmayla üretilmiş herhangi bir ürünün AB pazarına arz edilmesini, piyasada bulundurulmasını veya AB’den ihraç edilmesini yasaklıyor. Tüzük 14 Aralık 2027’den itibaren uygulanıyor; Avrupa Komisyonu rehberini 30 Haziran 2026’da yayımladı.", "page": 2}, {"title": "Eşik yok, güvenli liman yok", "explanation": "Yasak şirketlere değil ürünlere uygulanıyor ve büyüklük eşiği yok. Zorla çalıştırma içerdiği tespit edilen bir ürün piyasadan çekilebilir ve masrafı işletmeciye ait olmak üzere bertaraf edilebilir; iyi bir durum tespiti tek başına yasağı önlemiyor.", "page": 2}, {"title": "Kanıt iş kazandırır", "explanation": "Hazır giyim ve tekstil ya da mevsimlik tarım işçiliği içeren ürünler gibi uzun ve emek yoğun zincirlerdeki Türk tedarikçiler için ticari soru basit: Bir AB alıcısı izlenebilirlik ve çalışma koşullarına dair kanıt istediğinde bunu hızlı ve inandırıcı biçimde sunabiliyor muyuz?", "page": 2}]', '[]', '["Hangi ürün ve girdilerimiz en yüksek zorla çalıştırma riskini taşıyor ve neden?", "Bu ürünleri her işlem adımına ve fason üreticiye kadar izleyebiliyor muyuz?", "Bu kademelerde çalışma koşullarına dair hangi kanıtımız var: denetimler, çalışan görüşmeleri, şikâyet kanalları?", "Bir AB alıcısının ayrıntılı izlenebilirlik talebine ne kadar hızlı yanıt verebiliriz?", "Hangi müşteri sözleşmeleri artık zorla çalıştırma veya izlenebilirlik maddesi içeriyor?", "Bir tedarikçide şüpheli bir durumu nasıl ele alıyoruz; kararı kim veriyor?", "Komisyonun risk veri tabanını veya tanınmış başka risk kaynaklarını kullanıyor muyuz?", "Bu konunun şirketteki sahibi kim ve yönetim kurulu bunu görüyor mu?"]', '23–24 Ekim 2026’da kontrol edilen resmî AB ve Türkiye kaynaklarının masa başı incelemesi ile Ganrich Advisory’nin Ekim 2026 Türkiye fırsat incelemesinin birleşimi.', 'Genel bilgi niteliğindedir; hukuki, gümrük, vergi veya mühendislik danışmanlığı değildir. Kurallar ve tarihler değişebilir; resmî kaynaklardan teyit edin. Müşteri çalışması veya sonucu anlatılmaz.', '["Türkiye", "European Union"]', '["Forced Labour Regulation", "Supply chain", "EU market access"]', '["Operating model"]', '["forced labour", "traceability", "textiles", "supply chain", "due diligence"]', 'fully_ungated', 'pdf-insights/492125d0-5706-4a92-a97c-d916dae88e29/v1/Ganrich-Zorla-Calistirma-Kaniti-TR.pdf', 'Ganrich-Zorla-Calistirma-Kaniti-TR.pdf', '0f866a18b0900c7474515a01e7b89ee0553fc60068624cddb3e63bdb2974dd7d', 'application/pdf', 270598, 1, 'reviewed', 'furkangul@ganrichadvisory.com', 'furkangul@ganrichadvisory.com', '2026-10-24T09:00:00.000Z', '2026-10-24T09:00:00.000Z');
INSERT INTO pdf_insight_versions (id, insight_id, version, r2_key, filename, checksum, file_size, uploaded_by, uploaded_at, status) VALUES ('1b7f0d0e-1a40-4c55-9c71-000000000015', '492125d0-5706-4a92-a97c-d916dae88e29', 1, 'pdf-insights/492125d0-5706-4a92-a97c-d916dae88e29/v1/Ganrich-Zorla-Calistirma-Kaniti-TR.pdf', 'Ganrich-Zorla-Calistirma-Kaniti-TR.pdf', '0f866a18b0900c7474515a01e7b89ee0553fc60068624cddb3e63bdb2974dd7d', 270598, 'furkangul@ganrichadvisory.com', '2026-10-24T09:00:00.000Z', 'current');
INSERT INTO pdf_insights (id, slug, language, title, subtitle, short_title, content_type, status, author, publication_date, data_period, page_count, reading_time, executive_thesis, short_summary, executive_summary, key_findings, leadership_implications, strategic_questions, methodology, limitations, regions, topics, expertise, keywords, gating_model, pdf_key, original_filename, checksum, mime_type, file_size, version, extraction_confidence, created_by, updated_by, created_at, updated_at) VALUES ('000f6369-de84-4414-bdc2-08221b881e12', 'turkiye-ets-paradan-once-olcum-000f6369', 'tr', 'Paradan önce ölçüm: Türkiye Emisyon Ticaret Sistemine hazırlık', 'Ağustos 2026’da yayımlanan ETS Yönetmeliği planlar, izinler ve doğrulanmış raporlarla başlıyor. Karbon fiyatı sonra geliyor.', 'Paradan önce ölçüm', 'Strategic Perspective', 'review_required', 'Ahmed Furkan Gul', '2026-10-24', 'Ekim 2026', 5, 15, 'Ağustos 2026’da yayımlanan ETS Yönetmeliği planlar, izinler ve doğrulanmış raporlarla başlıyor. Karbon fiyatı sonra geliyor.', '7552 sayılı İklim Kanunu 9 Temmuz 2025’te yayımlandı ve ulusal emisyon ticaret sisteminin hukuki temelini oluşturdu. Türkiye Emisyon Ticaret Sistemi Yönetmeliği 27 Ağustos 2026 tarihli ve 33353 sayılı Resmî Gazete’de yayımlanarak aynı gün yürürlüğe girdi.', '7552 sayılı İklim Kanunu 9 Temmuz 2025’te yayımlandı ve ulusal emisyon ticaret sisteminin hukuki temelini oluşturdu. Türkiye Emisyon Ticaret Sistemi Yönetmeliği 27 Ağustos 2026 tarihli ve 33353 sayılı Resmî Gazete’de yayımlanarak aynı gün yürürlüğe girdi. Yıllık emisyonu 50.000 ton CO2 eşdeğerinin üzerindeki tesisler ETS kapsamında. Listelenen faaliyetlerdeki daha küçük tesisler de emisyonlarını izlemek, raporlamak ve doğrulatmak zorunda. Kapsamdaki işletmecilerin sera gazı emisyon iznine, onaylı izleme planına ve 30 Nisan’a kadar sunulan yıllık doğrulanmış emisyon raporuna ihtiyacı var. Pilot dönem; izleme, raporlama, doğrulama ve tahsisi maliyetler devreye girmeden test etmek için tasarlandı. Bu da veriyi doğru kurmanın en ucuz anı. Aynı veri, AB alıcılarının CBAM kapsamında istediği emisyon rakamlarının da temeli.', '[{"title": "Hukuki temel hazır", "explanation": "7552 sayılı İklim Kanunu 9 Temmuz 2025’te yayımlandı ve ulusal emisyon ticaret sisteminin hukuki temelini oluşturdu. Türkiye Emisyon Ticaret Sistemi Yönetmeliği 27 Ağustos 2026 tarihli ve 33353 sayılı Resmî Gazete’de yayımlanarak aynı gün yürürlüğe girdi.", "page": 2}, {"title": "Eşikler ve yükümlülükler", "explanation": "Yıllık emisyonu 50.000 ton CO2 eşdeğerinin üzerindeki tesisler ETS kapsamında. Listelenen faaliyetlerdeki daha küçük tesisler de emisyonlarını izlemek, raporlamak ve doğrulatmak zorunda. Kapsamdaki işletmecilerin sera gazı emisyon iznine, onaylı izleme planına ve 30 Nisan’a kadar sunulan yıllık doğrulanmış emisyon raporuna ihtiyacı var.", "page": 2}, {"title": "Pilot en ucuz an", "explanation": "Pilot dönem; izleme, raporlama, doğrulama ve tahsisi maliyetler devreye girmeden test etmek için tasarlandı. Bu da veriyi doğru kurmanın en ucuz anı. Aynı veri, AB alıcılarının CBAM kapsamında istediği emisyon rakamlarının da temeli.", "page": 2}]', '[]', '["Tesislerimizin her biri hangi kategoride; eşiğe yakın olan var mı?", "Geçerli bir emisyon iznimiz var mı, yoksa ne zaman başvurmamız gerektiğini biliyor muyuz?", "İzleme planımız onaylı, güncel ve tesisin gerçek işleyişiyle uyumlu mu?", "Yakıt, malzeme ve üretim verisi nereden geliyor; sayaçlar ne kadar güvenilir?", "Yıllık raporu kim hazırlıyor ve hangi akredite doğrulayıcı kontrol edecek?", "Ücretsiz tahsis ve emisyon izni fiyatları ilk uygulama döneminde marjlarımızı nasıl etkileyebilir?", "Aynı veri AB müşterilerimizin CBAM taleplerine de hizmet edebilir mi?", "Karbon verisinin şirketteki sahibi kim ve yönetim bunu ne sıklıkla görüyor?"]', '23–24 Ekim 2026’da kontrol edilen resmî AB ve Türkiye kaynaklarının masa başı incelemesi ile Ganrich Advisory’nin Ekim 2026 Türkiye fırsat incelemesinin birleşimi.', 'Genel bilgi niteliğindedir; hukuki, gümrük, vergi veya mühendislik danışmanlığı değildir. Kurallar ve tarihler değişebilir; resmî kaynaklardan teyit edin. Müşteri çalışması veya sonucu anlatılmaz.', '["Türkiye", "European Union"]', '["Türkiye ETS", "Carbon", "Industrial plants"]', '["Operating model"]', '["Türkiye ETS", "emissions trading", "MRV", "monitoring plan", "CBAM"]', 'fully_ungated', 'pdf-insights/000f6369-de84-4414-bdc2-08221b881e12/v1/Ganrich-Turkiye-ETS-Hazirligi-TR.pdf', 'Ganrich-Turkiye-ETS-Hazirligi-TR.pdf', 'e7ec5d3459b2a17b8fa9f22d7bea48dcb868c049ce1698766d7a441392fc4844', 'application/pdf', 272475, 1, 'reviewed', 'furkangul@ganrichadvisory.com', 'furkangul@ganrichadvisory.com', '2026-10-24T09:00:00.000Z', '2026-10-24T09:00:00.000Z');
INSERT INTO pdf_insight_versions (id, insight_id, version, r2_key, filename, checksum, file_size, uploaded_by, uploaded_at, status) VALUES ('1b7f0d0e-1a40-4c55-9c71-000000000016', '000f6369-de84-4414-bdc2-08221b881e12', 1, 'pdf-insights/000f6369-de84-4414-bdc2-08221b881e12/v1/Ganrich-Turkiye-ETS-Hazirligi-TR.pdf', 'Ganrich-Turkiye-ETS-Hazirligi-TR.pdf', 'e7ec5d3459b2a17b8fa9f22d7bea48dcb868c049ce1698766d7a441392fc4844', 272475, 'furkangul@ganrichadvisory.com', '2026-10-24T09:00:00.000Z', 'current');
